import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n_str = input_data[0]
    m = int(input_data[1])
    words = input_data[2:2 + m]

    mapping = {
        'a': '2', 'b': '2', 'c': '2',
        'd': '3', 'e': '3', 'f': '3',
        'g': '4', 'h': '4', 'i': '4',
        'j': '5', 'k': '5', 'l': '5',
        'm': '6', 'n': '6', 'o': '6',
        'p': '7', 'q': '7', 'r': '7', 's': '7',
        't': '8', 'u': '8', 'v': '8',
        'w': '9', 'x': '9', 'y': '9', 'z': '9'
    }

    target_len = len(n_str)
    count = 0

    for word in words:
        if len(word) != target_len:
            continue

        match = True
        for char, digit in zip(word, n_str):
            if mapping[char] != digit:
                match = False
                break

        if match:
            count += 1

    print(count)

if __name__ == '__main__':
    solve()
